import { NextApiRequest, NextApiResponse } from "next";
import { getLog4brainsInstance } from "../../lib/core-api";

function isRevalidateBody(body: unknown): body is { relativePath: string } {
  return (
    typeof body === "object" &&
    body !== null &&
    "relativePath" in body &&
    typeof body.relativePath === "string"
  );
}

/**
 * Preview mode: regenerates the pages affected by a changed ADR file, before the browser is notified (Hot Reload).
 * Called by the preview server (cli/commands/preview.ts) with the token it generated at startup.
 * The other pages are regenerated by ISR on their next visit (see lib/revalidate.ts).
 */
export default async (
  req: NextApiRequest,
  res: NextApiResponse
): Promise<void> => {
  const token = process.env.LOG4BRAINS_REVALIDATE_TOKEN;
  if (
    req.method !== "POST" ||
    !token ||
    req.headers["x-log4brains-token"] !== token
  ) {
    res.status(404).send("Not Found");
    return;
  }
  const body: unknown = req.body;
  if (!isRevalidateBody(body)) {
    res.status(400).send("Bad Request");
    return;
  }

  const changedPath = body.relativePath.toLowerCase();
  const adrs = await getLog4brainsInstance().searchAdrs();
  const changedAdr = adrs.find(
    (adr) => adr.file.relativePath.toLowerCase() === changedPath
  );
  const paths = ["/"];
  if (changedAdr) {
    paths.push(
      ...adrs
        .filter(
          (adr) =>
            adr.slug === changedAdr.slug || adr.supersededBy === changedAdr.slug // they display its title
        )
        .map((adr) => `/adr/${adr.slug}/`)
    );
  }

  await Promise.all(paths.map((path) => res.revalidate(path)));
  res.status(200).json({ revalidated: paths });
};
